#!/usr/bin/env bash
set -euo pipefail
mkdir -p client/src/products client/src/api
cat > client/package.json <<'EOF'
{
  "name": "product-picker-client",
  "private": true,
  "type": "module",
  "devDependencies": { "@umbraco-cms/backoffice": "^17.6.0", "typescript": "^5.9.0", "vite": "^7.0.0" }
}
EOF
cat > client/src/api/index.ts <<'EOF'
// Generated by @hey-api/openapi-ts from the package's Management API.
export interface ProductDetailsResponse {
	key: string;
	name: string;
	sku: string;
	price: string;
	/** The product page's "Description" rich text, rendered to HTML by the server. */
	descriptionHtml: string;
	/** The "Shipping notes" rich text, rendered to HTML by the server. */
	shippingNotesHtml: string;
}
export class ProductsService {
	static getDetails(options: { path: { key: string } }): Promise<{ data?: ProductDetailsResponse; error?: unknown }> {
		throw new Error('generated');
	}
}
EOF
cat > client/src/products/product-details.data-source.ts <<'EOF'
import type { UmbControllerHost } from '@umbraco-cms/backoffice/controller-api';
import { tryExecute } from '@umbraco-cms/backoffice/resources';
import { ProductsService, type ProductDetailsResponse } from '../api/index.js';

export class ProductDetailsDataSource {
	#host: UmbControllerHost;
	constructor(host: UmbControllerHost) {
		this.#host = host;
	}
	async get(key: string): Promise<{ data?: ProductDetailsResponse; error?: unknown }> {
		return tryExecute(this.#host, ProductsService.getDetails({ path: { key } }));
	}
}
EOF
cat > client/src/products/product-preview-card.element.ts <<'EOF'
import { css, customElement, html, property, state, unsafeHTML } from '@umbraco-cms/backoffice/external/lit';
import { UmbLitElement } from '@umbraco-cms/backoffice/lit-element';
import type { ProductDetailsResponse } from '../api/index.js';
import { ProductDetailsDataSource } from './product-details.data-source.js';

/** The card shown when hovering a product in the picker. */
@customElement('product-picker-preview-card')
export class ProductPickerPreviewCardElement extends UmbLitElement {
	@property() productKey = '';
	@state() private _product?: ProductDetailsResponse;
	#source = new ProductDetailsDataSource(this);

	override async updated(changed: Map<string, unknown>) {
		if (changed.has('productKey') && this.productKey) {
			const { data } = await this.#source.get(this.productKey);
			this._product = data;
		}
	}

	override render() {
		if (!this._product) return html`<uui-loader-bar></uui-loader-bar>`;
		return html`
			<uui-box headline=${this._product.name}>
				<small>${this._product.sku} · ${this._product.price}</small>
				<div class="description">${unsafeHTML(this._product.descriptionHtml)}</div>
			</uui-box>
		`;
	}

	static override styles = css`
		.description {
			margin-top: var(--uui-size-space-3);
		}
	`;
}

export default ProductPickerPreviewCardElement;
EOF
